<?php if($s->enabled('checkout')): ?><p class="section"><a class="btn" href="<?= e(url('checkout',['cart'=>1])) ?>"><?= icon('shield') ?><?= t('Checkout with shipping and direct payment') ?></a></p><?php endif ?><?php partial('account_nav',['route'=>$route]);$cart=\Chengyu\Services\Cart::lines();$totals=['balance'=>0,'points'=>0,'tokens'=>0];$physical=false; ?>
<section class="page-hero"><div><span class="eyebrow">SAVE GOOD THINGS FOR LATER</span><h1><?= e($title) ?></h1><p><?= t('The bag stays in this browser session. Prices and stock are checked again at purchase.') ?></p></div><span class="page-hero-art"><?= icon('box') ?></span></section><div class="two-column"><section class="panel glass">
<?php foreach($cart as $line):$entry=null;$variant=null;$id=$line['item_id'];$qty=$line['quantity'];try{$entry=$a->content->get($id,$me);if($line['variant_id']){$variant=$a->db->one('SELECT * FROM cy_variants WHERE id=? AND content_id=? AND active=1',[$line['variant_id'],$id]);if(!$variant){$entry=null;}}}catch(\Chengyu\Core\Problem $e){} ?>
<div class="cart-row"><?php if($entry):$amount=$variant?(int)$variant['price_amount']:(int)$entry['price_amount'];$amount=$a->pricing->price($entry,$me,$amount)['amount'];$totals[$entry['price_currency']]+=$amount*$qty;$physical=$physical||$entry['product_type']==='physical'; ?><img src="<?= e(cover($entry)) ?>" alt=""><div class="grow"><h3><a href="<?= e(item_url($entry)) ?>"><?= e($entry['title']) ?></a></h3><?php if($variant): ?><span class="pill"><?= e($variant['name']) ?></span><?php endif ?><p><?= e(price($amount,$entry['price_currency'])) ?> &times; <?= (int)$qty ?></p><?= form_start('cart_add') . hidden('item_id',$id) . hidden('variant_id',$line['variant_id']) ?><?php field('quantity','Quantity',$qty,'number',['min'=>'1','max'=>$entry['product_type']==='digital'?'1':'10']);button('Update','ghost small','refresh'); ?></form></div><?php else: ?><p class="grow"><?= t('This product is no longer available. Remove it before checkout.') ?> #<?= (int)$id ?></p><?php endif ?><?= form_start('cart_remove') . hidden('item_id',$id) . hidden('variant_id',$line['variant_id']) ?><?php button('Remove','ghost small','close'); ?></form></div><?php endforeach ?><?php if(!$cart){empty_state('Your collection bag is empty.','box');} ?></section>
<section class="panel glass"><h2><?= t('Order summary') ?></h2><?php foreach($totals as $currency=>$value):if(!$value){continue;} ?><div class="summary-row"><span><?= t($currency) ?></span><strong><?= e(price($value,$currency)) ?></strong></div><?php endforeach ?><?php if($cart): ?><?= form_start('cart_checkout') . intent() ?><?php foreach($totals as $currency=>$ceiling){echo hidden('ceiling_'.$currency,$ceiling);}if($physical){address_select((int)$me['id']);}button('Purchase the whole bag','full','lock'); ?><p class="hint"><?= t('One order per unit. The whole checkout rolls back if any item fails. Coupons are available on individual item purchases, not cart checkout.') ?></p></form><?php endif ?><a class="text-link" href="<?= e(url('shop')) ?>"><?= t('Keep exploring') ?><?= icon('arrow') ?></a></section></div>
